begin;
create extension if not exists pgcrypto;
create table if not exists public.invoice_counters (user_id uuid primary key references auth.users(id) on delete cascade,value bigint not null default 0 check(value>=0));
create table if not exists public.customers (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 2 and 160),type text not null default 'legal' check(type in('person','legal')),national_id text not null default '',phone text not null default '',email text not null default '',address text not null default '',active boolean not null default true,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,name text not null check(char_length(trim(name)) between 2 and 160),code text not null default '',type text not null default 'service' check(type in('product','service')),unit text not null default 'عدد',sell_price numeric(18,2) not null default 0 check(sell_price>=0),tax_percent numeric(5,2) not null default 0 check(tax_percent between 0 and 100),active boolean not null default true,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.seller_settings (user_id uuid primary key default auth.uid() references auth.users(id) on delete cascade,business_name text not null default '',national_id text not null default '',economic_code text not null default '',phone text not null default '',email text not null default '',bank_account text not null default '',address text not null default '',updated_at timestamptz not null default now());
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,invoice_number text,customer_id uuid references public.customers(id) on delete restrict,customer_name text not null,customer_national_id text not null default '',issue_date text not null,due_date text not null default '',reference text not null default '',items jsonb not null default '[]'::jsonb check(jsonb_typeof(items)='array'),subtotal numeric(18,2) not null default 0,line_discount numeric(18,2) not null default 0,discount_percent numeric(5,2) not null default 0,invoice_discount_amount numeric(18,2) not null default 0,tax numeric(18,2) not null default 0,total numeric(18,2) not null default 0 check(total>=0),paid_amount numeric(18,2) not null default 0 check(paid_amount>=0),payment_method text not null default 'نقدی',notes text not null default '',document_status text not null default 'draft' check(document_status in('draft','issued','void')),voided_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,invoice_number));
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end; $$;
create or replace function public.assign_invoice_number() returns trigger language plpgsql security definer set search_path='' as $$ declare next_value bigint;begin if new.user_id is null then new.user_id:=auth.uid();end if;if new.invoice_number is null or btrim(new.invoice_number)='' then insert into public.invoice_counters(user_id,value) values(new.user_id,1) on conflict(user_id) do update set value=public.invoice_counters.value+1 returning value into next_value;new.invoice_number:='FI-'||lpad(next_value::text,6,'0');end if;return new;end; $$;
drop trigger if exists customers_touch on public.customers;create trigger customers_touch before update on public.customers for each row execute function public.touch_updated_at();
drop trigger if exists products_touch on public.products;create trigger products_touch before update on public.products for each row execute function public.touch_updated_at();
drop trigger if exists seller_touch on public.seller_settings;create trigger seller_touch before update on public.seller_settings for each row execute function public.touch_updated_at();
drop trigger if exists invoices_touch on public.invoices;create trigger invoices_touch before update on public.invoices for each row execute function public.touch_updated_at();
drop trigger if exists invoices_number on public.invoices;create trigger invoices_number before insert on public.invoices for each row execute function public.assign_invoice_number();
alter table public.invoice_counters enable row level security;alter table public.customers enable row level security;alter table public.products enable row level security;alter table public.seller_settings enable row level security;alter table public.invoices enable row level security;
do $$ declare t text;begin foreach t in array array['invoice_counters','customers','products','seller_settings','invoices'] loop execute format('drop policy if exists owner_all on public.%I',t);execute format('create policy owner_all on public.%I for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t);end loop;end $$;
create index if not exists customers_user_active_idx on public.customers(user_id,active,created_at desc);create index if not exists products_user_active_idx on public.products(user_id,active,created_at desc);create index if not exists invoices_user_created_idx on public.invoices(user_id,created_at desc);create index if not exists invoices_user_status_idx on public.invoices(user_id,document_status,issue_date desc);
revoke all on public.invoice_counters from anon,authenticated;grant select,insert,update,delete on public.customers,public.products,public.seller_settings,public.invoices to authenticated;
commit;
